insert into public.reference_incidents
  (title, symptom_text, fingerprint, failure_mode, correct_first_branch, wrong_first_branch_taken, loss_description, root_cause, source_note)
values
  ('GitHub broad latency after datastore major-version upgrade', 'Issues, pull requests, notifications, Actions, repositories, API and login showed elevated latency and timeouts; unauthenticated traffic was hit hardest.', array['latency','timeouts','issues','pull','requests','notifications','actions','repositories','login','datastore','upgrade','contention']::text[], 'context_blindness', 'Check shared data-store saturation and resource contention introduced by the infrastructure upgrade; compare affected services by common datastore dependency and roll back the upgrade.', null, 'Source does not quantify diagnostic delay; service impact continued until rollback.', 'Unexpected resource contention after a major-version datastore infrastructure upgrade caused slow queries and distributed timeouts.', 'GH-2026-01-15-DATASTORE-UPGRADE | GitHub availability report: January 2026 | https://github.blog/news-insights/company-news/github-availability-report-january-2026/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('Dependabot degraded after compute security policy blocked VM metadata', 'Dependabot failed to create a portion of automated pull requests while VM create, delete and reimage operations failed in the underlying compute environment.', array['dependabot','pull','requests','virtual','machine','create','reimage','metadata','storage','policy','telemetry','compute']::text[], 'context_blindness', 'Inspect the compute-provider control plane and recent security-policy changes affecting VM metadata access, rather than treating Dependabot itself as the primary failure domain.', null, 'The incident persisted until the policy changes were rolled back and compute capacity recovered.', 'A loss of telemetry cascaded into security policies that blocked access to critical VM metadata, breaking VM lifecycle operations.', 'GH-2026-02-02-DEPENDABOT-COMPUTE-POLICY | GitHub availability report: February 2026 | https://github.blog/news-insights/company-news/github-availability-report-february-2026/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('GitHub-wide degradation from user-settings cache rewrite storm', 'github.com, API, Actions, HTTPS Git operations and Copilot failed together while SSH Git operations remained healthy.', array['github','errors','https','ssh','healthy','actions','copilot','cache','rewrites','background','connections','exhaustion']::text[], 'context_blindness', 'Use the protocol asymmetry and shared service impact to inspect the user-settings cache rewrite path, background-work coordinator and HTTPS proxy connection exhaustion.', null, 'Two related degradation periods produced roughly 2 hours 43 minutes of customer impact.', 'A cache configuration change triggered simultaneous rewrites that overwhelmed shared background infrastructure and exhausted connections in the HTTPS Git proxy.', 'GH-2026-02-09-CACHE-REWRITE-STORM | GitHub availability report: February 2026 | https://github.blog/news-insights/company-news/github-availability-report-february-2026/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('Regional Codespaces provisioning failures after authorization-claim change', 'Codespace create and resume failures spread progressively across Europe, Asia and Australia while US regions remained healthy.', array['codespaces','create','resume','regional','europe','asia','australia','provisioning','authorization','claim','networking','pool']::text[], 'context_blindness', 'Inspect regionally rolled-out networking authorization claims and pool-provisioning dependencies; compare unaffected US regions against impacted regions.', null, 'Low-severity alerting delayed incident detection and response.', 'An authorization-claim change in a core networking dependency caused Codespaces pool-provisioning failures.', 'GH-2026-02-12-CODESPACES-AUTH-CLAIM | GitHub availability report: February 2026 | https://github.blog/news-insights/company-news/github-availability-report-february-2026/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('Git LFS archive downloads failed after network misconfiguration', 'Repository zip and tar downloads failed only when archives included Git LFS objects; standard archives were unaffected.', array['archive','download','zip','tar','large','files','objects','standard','unaffected','health','checks','network']::text[], 'false_pattern_match', 'Branch immediately into the LFS-specific service path and its health-check/network configuration, not the generic repository archive pipeline.', null, 'Customer impact continued until the network setting was manually corrected.', 'An incorrect LFS network configuration made health checks fail and caused an internal service to be marked unreachable.', 'GH-2026-02-12-LFS-HEALTHCHECK-CONFIG | GitHub availability report: February 2026 | https://github.blog/news-insights/company-news/github-availability-report-february-2026/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('GitHub degradation repeated after high-volume user-settings cache writes', 'github.com and API failure rates rose sharply; HTTP Git and Copilot degraded while SSH was comparatively unaffected.', array['github','api','failures','http','ssh','copilot','settings','cache','writes','repeat','previous','incident']::text[], 'context_blindness', 'Compare the signature against the February cache-rewrite incident and inspect user-settings write volume and shared cache infrastructure first.', 'Treating the event as an unrelated new multi-service outage instead of checking the known February cache-write failure mode.', 'The source identifies recurrence; exact diagnostic time lost is not disclosed.', 'High-volume writes to the user-settings caching mechanism recreated the same underlying failure class as an earlier incident.', 'GH-2026-03-03-RECURRING-CACHE-WRITES | GitHub availability report: March 2026 | https://github.blog/news-insights/company-news/github-availability-report-march-2026/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('GitHub Actions queue degradation from Redis load-balancer misrouting', 'Most Actions workflows failed to start within five minutes, queue delays reached roughly 30 minutes, and some jobs returned infrastructure errors.', array['actions','workflow','start','delay','queue','infrastructure','errors','redis','load','balancer','routing','host']::text[], 'false_pattern_match', 'Inspect the Actions queue''s Redis routing and recent load-balancer changes before debugging individual runners or workflow definitions.', null, 'The queue required additional recovery time after the misconfiguration was corrected.', 'Incorrect Redis load-balancer configuration routed internal traffic to the wrong host.', 'GH-2026-03-05-REDIS-LB-MISROUTE | GitHub availability report: March 2026 | https://github.blog/news-insights/company-news/github-availability-report-march-2026/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('GitHub-to-Teams notifications failed during upstream dependency outage', 'GitHub event notifications to Teams failed with HTTP 500s and connection resets while unrelated GitHub services remained available.', array['teams','integration','notifications','delivery','http','errors','connection','resets','upstream','dependency','installations']::text[], 'context_blindness', 'Check the Teams integration''s upstream dependency health and connection-reset pattern before modifying GitHub event production or customer installation state.', null, 'Notifications were unavailable until the upstream incident was mitigated.', 'An upstream dependency outage caused HTTP 500 errors and connection resets for the Teams integration.', 'GH-2026-03-24-TEAMS-UPSTREAM | GitHub availability report: March 2026 | https://github.blog/news-insights/company-news/github-availability-report-march-2026/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('Audit-log datastore connectivity lost after credential rotation', 'Audit-log history was unavailable through API and web UI; events were delayed but ultimately not lost.', array['audit','logs','history','unavailable','events','delayed','datastore','connectivity','credential','rotation','authentication']::text[], 'anchoring', 'Inspect secret-rotation state and datastore authentication before investigating event loss or application query logic.', null, 'Detection began six minutes after onset; event delivery was delayed up to 29 minutes.', 'A failed credential rotation caused the audit-log service to lose connectivity to its backing datastore.', 'GH-2026-04-01-AUDIT-CREDENTIAL-ROTATION | GitHub availability report: April 2026 | https://github.blog/news-insights/company-news/github-availability-report-april-2026/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('Copilot coding-agent sessions stalled under globally scoped rate limit', 'New agent sessions queued for tens of minutes and failed in repeated waves after API request volume increased several-fold.', array['copilot','agent','sessions','queue','delay','rate','limit','global','installation','traffic','cache','credentials']::text[], 'context_blindness', 'Inspect rate-limit scope, shared credentials and cached rate-limit state before scaling workers or debugging agent execution itself.', null, 'About 22,700 workflow creations were delayed or failed during the incident.', 'Rate limiting was incorrectly global rather than per installation, compounded by traffic growth and a cache bug that prolonged the limited state.', 'GH-2026-04-09-CODING-AGENT-GLOBAL-RATE-LIMIT | GitHub availability report: April 2026 | https://github.blog/news-insights/company-news/github-availability-report-april-2026/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('GitHub Pages failures from shared DNS resolver cascade', 'Pages returned large volumes of HTTP 500s while services needing internal APIs, providers and storage failed together; cached lookups remained partly healthy.', array['pages','http','errors','dns','resolver','cached','lookups','internal','apis','storage','traffic','balancing']::text[], 'anchoring', 'Check internal DNS resolver health and the recently introduced traffic-balancing layer; use cache-hit versus cache-miss behavior to confirm.', null, 'An initial configuration rollback did not resolve the issue; resolver restart restored service.', 'A traffic-balancing mechanism failed under a specific load pattern and caused DNS resolvers to fail.', 'GH-2026-04-13-PAGES-DNS-CASCADE | GitHub availability report: April 2026 | https://github.blog/news-insights/company-news/github-availability-report-april-2026/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('GitHub search degraded when fronting load balancers saturated', 'Issues, pull requests, projects, repositories, Actions, package registry and Dependabot searches timed out or errored together.', array['search','timeouts','issues','pull','requests','projects','repositories','actions','packages','dependabot','load','balancer','saturation']::text[], 'context_blindness', 'Map the failures to the common search dependency and inspect saturation in the load-balancing tier in front of search, not each consuming product.', null, 'Some search targets saw failure rates up to 65% during the peak window.', 'The load-balancing tier in front of search infrastructure saturated, degrading connectivity.', 'GH-2026-04-27-SEARCH-LB-SATURATION | GitHub availability report: April 2026 | https://github.blog/news-insights/company-news/github-availability-report-april-2026/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('GitHub disruption from online schema migration saturating DB connections', 'Pull requests were most affected, while Issues, Actions, webhooks, Git operations and many dependent services showed latency and intermittent errors near traffic peak.', array['pull','requests','latency','errors','issues','actions','webhooks','database','connections','schema','migration','traffic']::text[], 'context_blindness', 'Inspect database connection capacity and long-running migration load; pause or throttle the migration before treating each affected product separately.', null, 'Customer impact lasted about an hour; the source does not disclose first-diagnosis delay.', 'Combined load from the schema migration and peak production traffic saturated database connection capacity.', 'GH-2026-05-04-SCHEMA-MIGRATION-CONNECTIONS | GitHub availability report: May 2026 | https://github.blog/news-insights/company-news/github-availability-report-may-2026/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('Copilot code review failed after dependency release incompatibility', 'Most requested code reviews returned a generic processing error while other GitHub functions remained available.', array['copilot','code','review','error','requests','dependency','release','runtime','incompatible','processing','workflow']::text[], 'false_pattern_match', 'Check upstream dependency health and runtime compatibility before tuning Copilot prompts, repository permissions or review-request payloads.', null, 'Approximately 36,800 review requests failed.', 'A newly released dependency was incompatible with the runtime environment.', 'GH-2026-06-04-COPILOT-DEPENDENCY-INCOMPATIBILITY | GitHub availability report: June 2026 | https://github.blog/news-insights/company-news/github-availability-report-june-2026/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('Copilot frontier models disappeared after invalid configuration change', 'Multiple frontier models disappeared from model pickers or returned model-not-available errors across web, editor and CLI; other models remained usable.', array['copilot','models','missing','unavailable','picker','editor','command','line','configuration','revert']::text[], 'context_blindness', 'Inspect shared model-availability configuration and revert the recent change rather than debugging each client or inference request path.', null, 'Affected models were unavailable for roughly 54 minutes.', 'An invalid production configuration change removed the affected models until the configuration was reverted.', 'GH-2026-06-17-COPILOT-MODEL-CONFIG | GitHub availability report: June 2026 | https://github.blog/news-insights/company-news/github-availability-report-june-2026/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('Background jobs delayed by hypervisor fault and connection storm', 'Pull requests, pushes, Actions and webhooks accumulated delays up to several minutes while a background-job node timed out and repeatedly rebalanced.', array['background','jobs','delays','pull','requests','pushes','actions','webhooks','timeouts','connections','rebalance','hypervisor']::text[], 'context_blindness', 'Inspect unhealthy queue nodes, connection churn and rebalance loops; remove the affected node before scaling every dependent service.', null, 'Delays peaked around seven minutes until the impacted node was replaced.', 'Underlying hypervisor issues and a traffic spike caused timeouts, a connection storm and continual rebalances.', 'GH-2026-06-25-BACKGROUND-CONNECTION-STORM | GitHub availability report: June 2026 | https://github.blog/news-insights/company-news/github-availability-report-june-2026/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('Cloudflare BYOIP customer prefixes unintentionally withdrawn', 'Only customers using Bring Your Own IP saw widespread timeouts and failed Internet connections; routes for their prefixes disappeared.', array['byoip','routes','withdrawn','bgp','timeouts','connect','unreachable','prefixes','internet','network','change']::text[], 'anchoring', 'Inspect BGP announcements and recent BYOIP onboarding-management changes before investigating customer origins or application health.', null, 'Affected customer services were unreachable until prefixes were restored.', 'A network-management change unintentionally withdrew customer BYOIP prefixes via BGP.', 'CF-2026-02-20-BYOIP-WITHDRAWAL | Cloudflare outage on February 20, 2026 | https://blog.cloudflare.com/cloudflare-outage-february-20-2026/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('1.1.1.1 global resolver outage after prefixes were withdrawn', 'UDP, TCP and DNS-over-TLS queries to 1.1.1.1 dropped globally while DNS-over-HTTPS using a different hostname/address path remained comparatively stable.', array['resolver','queries','dropped','global','udp','tcp','tls','https','stable','bgp','prefixes','withdrawn','anycast']::text[], 'anchoring', 'Inspect anycast prefix advertisements and the latest service-topology refresh; compare affected resolver IP paths against unaffected DoH paths.', 'Treating a visible BGP-origin anomaly as the cause rather than checking Cloudflare''s own route withdrawals.', 'Resolver service was unavailable globally for 62 minutes.', 'A legacy service-topology misconfiguration linked 1.1.1.1 prefixes to a non-production service, causing global route withdrawals during a later refresh.', 'CF-2025-07-14-RESOLVER-ROUTE-WITHDRAWAL | Cloudflare 1.1.1.1 incident on July 14, 2025 | https://blog.cloudflare.com/cloudflare-1-1-1-1-incident-on-july-14-2025/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('Cloudflare control plane failed after complete data-center power loss exposed hidden dependencies', 'Customer configuration APIs, dashboard and analytics failed while the traffic-serving data plane largely continued operating.', array['dashboard','api','analytics','logs','control','plane','traffic','working','data','center','power','kafka','clickhouse','dependency']::text[], 'context_blindness', 'Treat data-plane health plus control-plane failure as a dependency-location problem; inspect facility reachability and non-redundant Kafka/ClickHouse dependencies.', null, 'Control-plane and analytics recovery extended across more than a day for some services.', 'A catastrophic data-center power failure combined with hidden single-facility dependencies and incomplete full-facility failover testing.', 'CF-2023-11-02-CONTROL-PLANE-DATACENTER | Post mortem on the Cloudflare Control Plane and Analytics Outage | https://blog.cloudflare.com/post-mortem-on-cloudflare-control-plane-and-analytics-outage/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('Tiered Cache requests returned 530 after tracing code cleared routing headers', 'HTTP 530 errors affected Tiered Cache, Images and Bandwidth Alliance requests, while content served from local cache remained healthy.', array['http','errors','tiered','cache','images','local','cache','healthy','dns','hostname','headers','tracing','rollout']::text[], 'anchoring', 'Correlate 530s with Tiered Cache upper-tier traversal and the tracing rollout; inspect whether control headers and origin hostname context survive the hop.', 'Investigating an internal DNS release that was occurring at the same time.', 'Teams made several investigative attempts before confirming the faulty CDN release; peak impact reached about 5% of HTTP requests.', 'Tracing integration cleared control headers needed by upper-tier requests, leaving internal DNS without the origin hostname and producing 530 errors.', 'CF-2022-10-25-TIERED-CACHE-HEADERS | Partial Cloudflare outage on October 25, 2022 | https://blog.cloudflare.com/partial-cloudflare-outage-on-october-25-2022/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('Cloudflare traffic outage across busiest locations after network configuration change', 'Traffic failed in 19 high-volume data centers while other locations continued operating normally.', array['traffic','outage','data','centers','locations','network','configuration','change','busiest','regions','unaffected']::text[], 'context_blindness', 'Inspect and revert the shared network configuration deployed to the exact impacted data-center cohort before treating the event as a global application failure.', null, 'The first center recovered about 31 minutes after onset and full recovery took roughly 75 minutes.', 'A network configuration change made during a resilience project caused traffic loss in 19 data centers.', 'CF-2022-06-21-NETWORK-CONFIG | Cloudflare outage on June 21, 2022 | https://blog.cloudflare.com/cloudflare-outage-on-june-21-2022/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('Cloudflare dashboard/API outage after critical patch-panel cables were removed', 'Dashboard and API connectivity failed after technicians retired hardware; diverse providers and facilities still shared one physical patch panel.', array['dashboard','api','connectivity','data','center','hardware','cables','patch','panel','physical','network','removed']::text[], 'context_blindness', 'Inspect the physical connectivity path and recent data-center work, especially shared patch panels and removed cables, before debugging application services.', null, 'Time was lost identifying which critical cables had to be restored.', 'Critical external-connectivity cables were removed from a shared patch panel, exposing a physical single point of failure.', 'CF-2020-04-15-PATCH-PANEL | Cloudflare Dashboard and API Outage on April 15, 2020 | https://blog.cloudflare.com/cloudflare-dashboard-and-api-outage-on-april-15-2020/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('Global Cloudflare 502 outage from bad rule causing CPU saturation', 'Cloudflare-proxied domains returned 502s globally at the same time edge CPU utilization spiked across the network.', array['global','http','errors','bad','gateway','cpu','spike','edge','software','deploy','rule','rollback','attack']::text[], 'anchoring', 'Correlate the CPU spike with the latest globally distributed rule/software deployment and roll it back immediately.', 'Treating the event as an external attack because of its global scale.', 'The global outage lasted roughly 30 minutes.', 'A bad software deployment caused massive CPU utilization across the edge network.', 'CF-2019-07-02-REGEX-CPU | Cloudflare outage caused by bad software deploy | https://blog.cloudflare.com/cloudflare-outage/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('Cloudflare disappeared from Internet after bad rule crashed edge routers', 'DNS queries failed, pings and traceroutes returned no route to host, and edge routers across data centers crashed.', array['dns','error','ping','traceroute','route','host','routers','crash','network','unreachable','rule']::text[], 'false_pattern_match', 'Treat no-route symptoms as a routing-control-plane failure; inspect the common router rule and remove it before debugging DNS or proxy applications.', null, 'Physical reboots across globally distributed data centers extended restoration.', 'A bad rule triggered system-wide edge-router crashes and route withdrawals.', 'CF-2013-03-03-ROUTER-RULE | Today''s Outage Post Mortem | https://blog.cloudflare.com/todays-outage-post-mortem-82515/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('Cloudflare outage after DDoS mitigation rate limit was misapplied', 'European network instability coincided with an upstream provider problem and active mitigation of a large DDoS.', array['europe','network','outage','upstream','provider','ddos','rate','limit','mitigation','connectivity']::text[], 'anchoring', 'Audit the just-applied mitigation rule and its scope while separately validating upstream reachability.', 'Attributing the entire outage to the upstream provider or to the DDoS alone.', 'The combined failure made customer sites unreachable; exact diagnostic delay is not disclosed.', 'An upstream network problem combined with a misapplied network rate limit during DDoS mitigation.', 'CF-2012-09-16-RATE-LIMIT | Post Mortem: What Yesterday''s Network Outage Looked Like | https://blog.cloudflare.com/post-mortem-what-todays-network-outage-looked/ | confidence=high | curated first-branch inference; see JSONL review_notes'),
  ('Cloudflare network outage from routing-policy failure', 'Approximately three quarters of Cloudflare traffic was disrupted across regions for up to about 15 minutes.', array['traffic','outage','regions','network','routes','routing','bgp','unreachable','application','healthy']::text[], 'false_pattern_match', 'Inspect BGP route announcements and shared router policy before application services or origin infrastructure.', null, 'A major portion of network traffic was unavailable during the incident.', 'A routing configuration/policy problem disrupted Cloudflare route availability across much of the network.', 'CF-2012-05-02-BGP-POLICY | Today''s Outage Post Mortem | https://blog.cloudflare.com/todays-outage-post-mortem/ | confidence=medium | curated first-branch inference; see JSONL review_notes');
